-- E-12 / S047-S048: user-supplied corrections for a precisely pinned free edition.
-- Status changes do not edit a chapter or claim that the text was corrected.
CREATE TABLE text_issues (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    book_id BIGINT NOT NULL REFERENCES books(id) ON DELETE CASCADE,
    chapter_id BIGINT NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,
    version_id BIGINT NOT NULL,
    reporter_user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    block_index INTEGER NOT NULL CHECK (block_index BETWEEN 1 AND 200),
    selection_start INTEGER NOT NULL CHECK (selection_start >= 0),
    selection_end INTEGER NOT NULL CHECK (selection_end > selection_start),
    quote TEXT NOT NULL CHECK (char_length(quote) BETWEEN 1 AND 500),
    suggested_text TEXT NOT NULL CHECK (char_length(suggested_text) BETWEEN 1 AND 1000),
    issue_type TEXT NOT NULL
        CHECK (issue_type IN ('typo', 'formatting', 'broken_link', 'factual', 'continuity', 'other')),
    request_hash BYTEA NOT NULL CHECK (octet_length(request_hash) = 32),
    status TEXT NOT NULL DEFAULT 'new'
        CHECK (status IN ('new', 'in_review', 'fixed', 'rejected')),
    resolution_note TEXT CHECK (resolution_note IS NULL OR char_length(resolution_note) <= 1000),
    resolved_by_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
    resolved_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (chapter_id, version_id)
        REFERENCES chapter_versions(chapter_id, id) ON DELETE RESTRICT,
    UNIQUE (reporter_user_id, chapter_id, version_id, block_index,
            selection_start, selection_end, request_hash)
);
CREATE INDEX text_issues_author_queue_idx
    ON text_issues(book_id, status, id DESC);
CREATE INDEX text_issues_book_recent_idx
    ON text_issues(book_id, id DESC);

CREATE TABLE text_issue_status_events (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    issue_id BIGINT NOT NULL REFERENCES text_issues(id) ON DELETE CASCADE,
    actor_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
    old_status TEXT NOT NULL,
    new_status TEXT NOT NULL,
    resolution_note TEXT,
    changed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX text_issue_status_events_issue_idx
    ON text_issue_status_events(issue_id, id);

COMMENT ON TABLE text_issues IS
    'Pinned reader correction for published free ChapterVersion, not an automatic edit or an entitlement.';
